package main

import "fmt"

func main() {
	months := [...]string{
		1:  "january",
		2:  "february",
		3:  "march",
		4:  "april",
		5:  "may",
		6:  "june",
		7:  "july",
		8:  "august",
		9:  "september",
		10: "october",
		11: "november",
		12: "december",
	}
	fmt.Println(months)

	q2 := months[4:7]
	fmt.Println(q2)
	summer := months[6:9]
	fmt.Println(summer)

	fmt.Println(len(q2))
	fmt.Println(cap(q2))
	fmt.Println(len(summer))
	fmt.Println(cap(summer))

	newslice := q2[:6]
	fmt.Println(newslice)

	org := []int{1, 2, 3, 4, 5, 6, 7, 8}
	fmt.Println(org)
	reverseSlice(org)
	fmt.Println(org)

}

func reverseSlice(org []int) {
	for i, j := 0, len(org)-1; i < j; i, j = i+1, j-1 {
		org[i], org[j] = org[j], org[i]
	}
}

func equals(x, y []string) bool {
	if len(x) != len(y) {
		return false
	}
	for i := range x {
		if x[i] != y[i] {
			return false
		}
	}
	return true
}

