package binaryTree

type tree struct {
	value      int
	leftChild  *tree
	rightChild *tree
}

func Sort(values []int) {
	var root *tree
	for _, v := range values {
		root = add(root, v)
	}
	appendValues(values[:0], root)
}

func add(curNode *tree, v int) *tree {
	if curNode == nil {
		return curNode
	}
	if v <= curNode.value {
		if curNode.leftChild == nil {
			curNode.leftChild = &tree{value: v}
		} else {
			add(curNode.leftChild, v)
		}
	} else {
		if curNode.rightChild == nil {
			curNode.rightChild = &tree{value: v}
		} else {
			add(curNode.rightChild, v)
		}
	}
	return curNode
}

func appendValues(arr []int, curNode *tree) {
	if curNode == nil {
		return
	}
	appendValues(arr, curNode.leftChild)
	arr = append(arr, curNode.value)
	appendValues(arr, curNode.rightChild)
}
